def inherited_faces(source):
    sn = bd.Vector(*n_at(source))
    found=[]
    for f in fluid.faces():
        fn=f.normal_at()
        if fn.dot(sn) > 1-1e-8 and source.distance_to(f.center()) < 1e-8:
            found.append(f)
    return found
